<body>
<div class="wrap">
  <h1>Cooking Unit Converter</h1>
  <p class="sub">Convert grams, millilitres, decilitres, cups, tablespoons and teaspoons.</p>
  <p class="hint">Type a value, pick units, then swap direction with the button. Results use ingredient densities for accurate weight-to-volume conversions.</p>

  <div class="card">
    <div class="grid">
      <div class="field">
        <label for="fromVal">From</label>
        <input id="fromVal" type="number" inputmode="decimal" value="1" step="any">
      </div>
      <div class="field">
        <label for="fromUnit">Unit</label>
        <select id="fromUnit"></select>
      </div>
      <div class="swap">
        <label>&nbsp;</label>
        <button id="swap" type="button" aria-label="Swap units">&#8646;</button>
      </div>
      <div class="field">
        <label for="toUnit">To</label>
        <select id="toUnit"></select>
      </div>
      <div class="field">
        <label for="ingredient">Ingredient (for weight &harr; volume)</label>
        <select id="ingredient"></select>
      </div>
    </div>
    <div class="result" id="result" aria-live="polite"></div>
  </div>

  <div class="card">
    <h2>Quick reference</h2>
    <table>
      <thead><tr><th>Measure</th><th class="num">Value</th></tr></thead>
      <tbody>
        <tr><td>1 US cup</td><td class="num">240 ml</td></tr>
        <tr><td>1 tablespoon</td><td class="num">15 ml</td></tr>
        <tr><td>1 teaspoon</td><td class="num">5 ml</td></tr>
        <tr><td>1 decilitre</td><td class="num">100 ml</td></tr>
        <tr><td>1 cup water</td><td class="num">240 g</td></tr>
        <tr><td>1 cup all-purpose flour</td><td class="num">125 g</td></tr>
        <tr><td>1 cup granulated sugar</td><td class="num">200 g</td></tr>
        <tr><td>1 cup butter</td><td class="num">227 g</td></tr>
      </tbody>
    </table>
  </div>
</div>

<script>
(function(){
  var UNITS = {
    ml:  { name:'Millilitres',  kind:'vol', base:1 },
    dl:  { name:'Decilitres',   kind:'vol', base:100 },
    l:   { name:'Litres',       kind:'vol', base:1000 },
    cup: { name:'US Cup',       kind:'vol', base:240 },
    tbsp:{ name:'Tablespoon',   kind:'vol', base:15 },
    tsp: { name:'Teaspoon',     kind:'vol', base:5 },
    g:   { name:'Grams',        kind:'wt',  base:1 },
    kg:  { name:'Kilograms',    kind:'wt',  base:1000 },
    oz:  { name:'Ounces',       kind:'wt',  base:28.3495 },
    lb:  { name:'Pounds',       kind:'wt',  base:453.592 }
  };
  var INGREDIENTS = {
    water:      { name:'Water',            density:1 },
    milk:       { name:'Milk',             density:1.03 },
    flour:      { name:'All-purpose flour',density:0.52 },
    sugar:      { name:'Granulated sugar', density:0.85 },
    butter:     { name:'Butter',           density:0.911 },
    oil:        { name:'Cooking oil',      density:0.91 },
    honey:      { name:'Honey',            density:1.42 },
    cocoa:      { name:'Cocoa powder',     density:0.45 },
    salt:       { name:'Salt',             density:1.2 },
    rice:       { name:'Rice',             density:0.85 },
    oats:       { name:'Rolled oats',      density:0.4 },
    bakingpow:  { name:'Baking powder',    density:0.65 }
  };

  var fromVal = document.getElementById('fromVal');
  var fromUnit = document.getElementById('fromUnit');
  var toUnit = document.getElementById('toUnit');
  var ingredient = document.getElementById('ingredient');
  var result = document.getElementById('result');
  var swap = document.getElementById('swap');

  function fill(sel, map, keep){
    var prev = keep ? sel.value : null;
    sel.innerHTML = '';
    Object.keys(map).forEach(function(k){
      var o = document.createElement('option');
      o.value = k; o.textContent = map[k].name;
      sel.appendChild(o);
    });
    if (prev && map[prev]) sel.value = prev;
  }
  fill(fromUnit, UNITS, false);
  fill(toUnit, UNITS, false);
  fill(ingredient, INGREDIENTS, false);
  fromUnit.value = 'g'; toUnit.value = 'cup'; ingredient.value = 'flour';

  function fmt(n){
    if (!isFinite(n)) return '—';
    if (n === 0) return '0';
    var a = Math.abs(n);
    var d = a >= 100 ? 0 : a >= 10 ? 1 : a >= 1 ? 2 : 3;
    return n.toFixed(d);
  }

  function convert(){
    var val = parseFloat(fromVal.value);
    var fu = UNITS[fromUnit.value], tu = UNITS[toUnit.value];
    if (isNaN(val)){ result.innerHTML = '<span class="u">Enter a value.</span>'; return; }
    var out;
    if (fu.kind === tu.kind){
      out = val * fu.base / tu.base;
    } else {
      var dens = INGREDIENTS[ingredient.value].density;
      if (fu.kind === 'wt' && tu.kind === 'vol'){
        out = (val * fu.base / dens) / tu.base;
      } else {
        out = (val * tu.base * dens) / fu.base;
      }
    }
    result.innerHTML = fmt(val) + ' ' + fu.name + ' = ' + fmt(out) + ' <span class="u">' + tu.name + '</span>';
  }

  swap.addEventListener('click', function(){
    var t = fromUnit.value; fromUnit.value = toUnit.value; toUnit.value = t;
    convert(); save();
  });
  [fromVal, fromUnit, toUnit, ingredient].forEach(function(el){
    el.addEventListener('input', function(){ convert(); save(); });
    el.addEventListener('change', function(){ convert(); save(); });
  });

  function save(){
    if (window.alfy && window.alfy.storage){
      window.alfy.storage.set('conv', {
        value: fromVal.value, from: fromUnit.value, to: toUnit.value, ing: ingredient.value
      });
    }
  }
  async function load(){
    if (window.alfy && window.alfy.storage){
      try {
        var s = await window.alfy.storage.get('conv');
        if (s){
          if (s.value != null) fromVal.value = s.value;
          if (s.from && UNITS[s.from]) fromUnit.value = s.from;
          if (s.to && UNITS[s.to]) toUnit.value = s.to;
          if (s.ing && INGREDIENTS[s.ing]) ingredient.value = s.ing;
        }
      } catch(e){}
    }
    convert();
  }
  load();
})();
</script>
</body>
</html>
